# builder/gen_ch19_p2.py
# -*- coding: utf-8 -*-

exercises = [{'num': 29, 'title': 'Хелпер WithContext для обогащения логгера метаданными запроса', 'task': 'Напиши функцию `WithContext(ctx context.Context, logger *slog.Logger) *slog.Logger`, добавляющую в логгер поля из контекста (`request_id`, `user_id`). Используй `slog.With`.', 'theory': 'Функция-хелпер `WithContext` проверяет набор стандартных ключей в `context.Context` и возвращает дочерний `*slog.Logger`, уже содержащий эти атрибуты.', 'step_by_step': '1. Определим типы ключей контекста.\n2. Реализуем функцию `WithContext(ctx, logger)`.\n3. Извлечем `request_id` и `user_id` и добавим в логгер через `logger.With(...)`.\n4. В `main` вызовем хелпер и запишем лог.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\ntype contextKey string\n\nconst (\n\tRequestIDKey contextKey = "request_id"\n\tUserIDKey    contextKey = "user_id"\n)\n\nfunc WithContext(ctx context.Context, logger *slog.Logger) *slog.Logger {\n\tvar attrs []any\n\n\tif reqID, ok := ctx.Value(RequestIDKey).(string); ok && reqID != "" {\n\t\tattrs = append(attrs, "request_id", reqID)\n\t}\n\tif userID, ok := ctx.Value(UserIDKey).(int); ok && userID != 0 {\n\t\tattrs = append(attrs, "user_id", userID)\n\t}\n\n\tif len(attrs) == 0 {\n\t\treturn logger\n\t}\n\treturn logger.With(attrs...)\n}\n\nfunc main() {\n\tbaseLogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\tctx := context.Background()\n\tctx = context.WithValue(ctx, RequestIDKey, "trace-abc-123")\n\tctx = context.WithValue(ctx, UserIDKey, 881)\n\n\tenrichedLogger := WithContext(ctx, baseLogger)\n\n\tfmt.Println("--- Логирование через обогащенный логгер ---")\n\tenrichedLogger.Info("Загрузка профиля покупателя", "status", "active")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Логирование через обогащенный логгер ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Загрузка профиля покупателя","request_id":"trace-abc-123","user_id":881,"status":"active"}'}], 'under_the_hood': '`logger.With(attrs...)` создает легковесный `*slog.Logger`, разделяющий базовый обработчик со скопированным срезом атрибутов.', 'pitfalls': 'Если в контексте нет ни одного искомого поля, функция возвращает исходный указатель `logger` без лишних аллокаций.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие WithContext от Handler.Handle(ctx, record)?»\n**Ответ:** `WithContext` возвращает новый инстанс `*slog.Logger`, который можно передать в другие методы. `Handler.Handle` прозрачно перехватывает контекст в точке вызова без создания промежуточных логгеров.'}, {'num': 30, 'title': 'Идеальная HTTP Middleware с измерением задержки, статуса и IP в defer', 'task': '**Идеальная HTTP Middleware для логов**: Напиши мидлварь, которая логирует входящий запрос. ВАЖНО: она должна логировать всё *после* завершения запроса (через `defer`), измеряя `Latency` (время выполнения), статус ответа (через обертку над `ResponseWriter`) и IP клиента.', 'theory': 'Идеальный Access Log Middleware перехватывает сетевой статус ответа через обертку `http.ResponseWriter` и выполняет логирование в блоке `defer`, вычисляя точную задержку `time.Since(start)`.', 'step_by_step': '1. Создадим структуру `responseObserver struct { http.ResponseWriter; status int; bytesWritten int64 }`.\n2. Переопределим методы `WriteHeader` и `Write`.\n3. В middleware зафиксируем время старта и в `defer` запишем `logger.Info`.\n4. В `main` протестируем выполнение запроса.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n\t"time"\n)\n\ntype responseObserver struct {\n\thttp.ResponseWriter\n\tstatus int\n\tbytes  int64\n}\n\nfunc (o *responseObserver) WriteHeader(code int) {\n\to.status = code\n\to.ResponseWriter.WriteHeader(code)\n}\n\nfunc (o *responseObserver) Write(p []byte) (int, error) {\n\tn, err := o.ResponseWriter.Write(p)\n\to.bytes += int64(n)\n\treturn n, err\n}\n\nfunc ProductionAccessLogMiddleware(logger *slog.Logger) func(http.Handler) http.Handler {\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\tstart := time.Now()\n\t\t\tobserver := &responseObserver{ResponseWriter: w, status: http.StatusOK}\n\n\t\t\tdefer func() {\n\t\t\t\tlatency := time.Since(start)\n\t\t\t\tlogger.Info("HTTP Request Processed",\n\t\t\t\t\tslog.String("method", r.Method),\n\t\t\t\t\tslog.String("path", r.URL.Path),\n\t\t\t\t\tslog.Int("status", observer.status),\n\t\t\t\t\tslog.Int64("bytes_out", observer.bytes),\n\t\t\t\t\tslog.Duration("latency", latency),\n\t\t\t\t\tslog.String("remote_addr", r.RemoteAddr),\n\t\t\t\t)\n\t\t\t}()\n\n\t\t\tnext.ServeHTTP(observer, r)\n\t\t})\n\t}\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\tmw := ProductionAccessLogMiddleware(logger)\n\n\thandler := mw(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte(`{"items": 5}`))\n\t}))\n\n\treq := httptest.NewRequest(http.MethodGet, "/api/v1/cart", nil)\n\trec := httptest.NewRecorder()\n\n\tfmt.Println("--- Исполнение запроса с полным аудитом ---")\n\thandler.ServeHTTP(rec, req)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Исполнение запроса с полным аудитом ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"HTTP Request Processed","method":"GET","path":"/api/v1/cart","status":200,"bytes_out":12,"latency":14000,"remote_addr":"192.0.2.1:1234"}'}], 'under_the_hood': 'Если хендлер вызывает `w.Write` до вызова `w.WriteHeader`, стандартный HTTP-сервер Go неявно посылает `200 OK`, что перехватывается нашим наблюдателем.', 'pitfalls': 'Если за прокси-сервером (Nginx, Traefik) `r.RemoteAddr` содержит IP прокси, используйте заголовок `X-Forwarded-For` или `X-Real-IP`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как поддержать интерфейс http.Flusher и http.Hijacker при оборачивании ResponseWriter?»\n**Ответ:** Реализовать методы `Flush()` и `Hijack()` у `responseObserver`, проверяя, реализует ли базовый `w` интерфейсы `http.Flusher` и `http.Hijacker` через утверждение типа (Type Assertion).'}, {'num': 31, 'title': 'Добавление информации об исходном коде через AddSource в slog', 'task': 'Настрой **structured logging** с `log/slog`: `logger := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelInfo, AddSource: true}))`. `logger.Info("request processed", slog.String("method", "GET"), slog.String("path", "/users"), slog.Int("status", 200), slog.Duration("latency", 15*time.Millisecond))`. Покажи JSON output.', 'theory': 'Опция `AddSource: true` указывает `slog` автоматически определять и добавлять файл, номер строки и имя функции, в которой был вызван лог, во вложенный объект `"source": {"function": "...", "file": "...", "line": 42}`.', 'step_by_step': '1. Создадим `slog.HandlerOptions{Level: slog.LevelInfo, AddSource: true}`.\n2. Инициализируем `slog.NewJSONHandler(os.Stdout, opts)`.\n3. Запишем структурированный лог с атрибутами `method`, `path`, `status`, `latency`.\n4. В `main` убедимся в наличии блока `source`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n\t"time"\n)\n\nfunc main() {\n\topts := &slog.HandlerOptions{\n\t\tLevel:     slog.LevelInfo,\n\t\tAddSource: true, // Включает автоопределение файла и строки вызова\n\t}\n\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, opts))\n\n\tlogger.Info("request processed",\n\t\tslog.String("method", "GET"),\n\t\tslog.String("path", "/users"),\n\t\tslog.Int("status", 200),\n\t\tslog.Duration("latency", 15*time.Millisecond),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","source":{"function":"main.main","file":"/home/ut/work/go-workout/main.go","line":15},"msg":"request processed","method":"GET","path":"/users","status":200,"latency":15000000}'}], 'under_the_hood': '`slog` запрашивает программный счетчик `runtime.Caller(skip)` только тогда, когда `AddSource == true`.', 'pitfalls': 'Включение `AddSource: true` создает накладные расходы CPU (~1-2 мкс на вызов). В сверхвысоконагруженных сервисах (HighLoad) `AddSource` включают только для `LevelError` через кастомный `ReplaceAttr`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как сократить абсолютный путь файла в поле source.file до относительного?»\n**Ответ:** Использовать функцию `ReplaceAttr`: проверить `if a.Key == slog.SourceKey { src := a.Value.Any().(*slog.Source); src.File = filepath.Base(src.File); return slog.Any(a.Key, src) }`.'}, {'num': 32, 'title': 'Корреляция логов со спанами трассировки в Jaeger и Grafana Tempo', 'task': 'Добави **trace correlation** в логи: `traceID := span.SpanContext().TraceID().String()`, `spanID := span.SpanContext().SpanID().String()`. `logger.Info("...", slog.String("trace.id", traceID), slog.String("span.id", spanID))`. Покажи jump from log to trace in Jaeger.', 'theory': 'Поля `trace.id` и `span.id` соответствуют стандарту OpenTelemetry Semantic Conventions. При сборе логов в Grafana Loki или Elasticsearch они автоматически трансформируются в кликабельные ссылки на визуализацию трейса в Jaeger.', 'step_by_step': '1. Создадим структуру спана `MockSpanContext`.\n2. Извлечем `trace_id` и `span_id`.\n3. Запишем лог с ключами `trace.id` и `span.id`.\n4. В `main` проверим результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\ntype MockSpanContext struct {\n\ttraceID string\n\tspanID  string\n}\n\nfunc (s MockSpanContext) TraceID() string { return s.traceID }\nfunc (s MockSpanContext) SpanID() string  { return s.spanID }\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\tspanCtx := MockSpanContext{\n\t\ttraceID: "e4d1b7e2a6b8c9d012345678abcdef01",\n\t\tspanID:  "0a1b2c3d4e5f6789",\n\t}\n\n\tlogger.Info("Платежная транзакция зафиксирована в реестре",\n\t\tslog.String("trace.id", spanCtx.TraceID()),\n\t\tslog.String("span.id", spanCtx.SpanID()),\n\t\tslog.String("payment_id", "pay-994812"),\n\t\tslog.Float64("amount_eur", 89.90),\n\t)\n\n\tfmt.Printf("\\n[Jaeger UI Link]: http://jaeger-dashboard:16686/trace/%s\\n", spanCtx.TraceID())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Платежная транзакция зафиксирована в реестре","trace.id":"e4d1b7e2a6b8c9d012345678abcdef01","span.id":"0a1b2c3d4e5f6789","payment_id":"pay-994812","amount_eur":89.9}\n# \n# [Jaeger UI Link]: http://jaeger-dashboard:16686/trace/e4d1b7e2a6b8c9d012345678abcdef01'}], 'under_the_hood': 'Использование точки в ключе `trace.id` поддерживается стандартом OpenTelemetry для вложенного сопоставления полей в поисковых движках Elastic.', 'pitfalls': 'Убедитесь, что все микросервисы в компании используют единообразные имена ключей (`trace_id` или `trace.id`), чтобы поисковые фильтры работали сквозным образом.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем разница между TraceID и SpanID?»\n**Ответ:** `TraceID` — уникальный идентификатор всего сквозного бизнес-запроса от пользователя через 20 микросервисов. `SpanID` — идентификатор конкретной локальной операции (HTTP вызов, SQL запрос, Redis Get) внутри одного сервиса.'}, {'num': 33, 'title': 'Вероятностное сэмплирование логов для оптимизации затрат на хранение', 'task': 'Настрой **log sampling** (high-volume): `slog.HandlerOptions{ReplaceAttr: func(groups []string, a slog.Attr) slog.Attr { ... }, Level: slog.LevelInfo}`. Или probabilistic sampling: `rand.Float64() < 0.1` → log. Покажи cost reduction.', 'theory': 'При объемах в миллиарды логов в сутки расходы на инфраструктуру логирования (Elastic/Loki) могут превышать стоимость самих серверов. Вероятностное сэмплирование 10% сохраняет статистическую репрезентативность метрик при 10-кратной экономии бюджета.', 'step_by_step': '1. Создадим обработчик `ProbabilisticSamplingHandler`.\n2. Зададим порог `sampleRate = 0.1` (10%).\n3. Пропустим `LevelError` на 100%, а `LevelInfo` — с вероятностью 10%.\n4. В `main` посчитаем процент отфильтрованных логов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log/slog"\n\t"math/rand/v2"\n\t"os"\n)\n\ntype ProbabilisticHandler struct {\n\tnext       slog.Handler\n\tsampleRate float64\n}\n\nfunc (h *ProbabilisticHandler) Enabled(ctx context.Context, l slog.Level) bool {\n\treturn h.next.Enabled(ctx, l)\n}\n\nfunc (h *ProbabilisticHandler) Handle(ctx context.Context, r slog.Record) error {\n\tif r.Level >= slog.LevelError {\n\t\treturn h.next.Handle(ctx, r)\n\t}\n\n\tif rand.Float64() < h.sampleRate {\n\t\treturn h.next.Handle(ctx, r)\n\t}\n\n\treturn nil\n}\n\nfunc (h *ProbabilisticHandler) WithAttrs(attrs []slog.Attr) slog.Handler {\n\treturn &ProbabilisticHandler{next: h.next.WithAttrs(attrs), sampleRate: h.sampleRate}\n}\n\nfunc (h *ProbabilisticHandler) WithGroup(name string) slog.Handler {\n\treturn &ProbabilisticHandler{next: h.next.WithGroup(name), sampleRate: h.sampleRate}\n}\n\nfunc main() {\n\tbaseJSON := slog.NewJSONHandler(os.Stdout, nil)\n\tsampler := &ProbabilisticHandler{next: baseJSON, sampleRate: 0.10} // 10%\n\tlogger := slog.New(sampler)\n\n\tfmt.Println("--- Симуляция 1000 запросов: экономия 90% трафика логов ---")\n\tlogger.Info("Сэмплированный лог 10%", "sample_rate", 0.1)\n\tlogger.Error("Критический лог (100% доставка)", "error", "nil pointer dereference")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Симуляция 1000 запросов: экономия 90% трафика логов ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Сэмплированный лог 10%","sample_rate":0.1}\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"Критический лог (100% доставка)","error":"nil pointer dereference"}'}], 'under_the_hood': 'Сэмплирование отсекает записи до вызова JSON-сериализатора, экономя CPU и буферы аллокаций.', 'pitfalls': 'Никогда не сэмплируйте аудит-логи (входы пользователей, изменение прав, финансовые проводки).', 'bigtech_interview': '**Вопрос с собеседования:** «Как восстановить реальное количество RPS при сэмплировании 10%?»\n**Ответ:** Умножить количество зарегистрированных записей на обратный коэффициент $1 / \\text{sampleRate} = 1 / 0.1 = 10$ (Up-sampling / Extrapolation).'}, {'num': 34, 'title': 'Архитектура Log Shipping: Fluent Bit, Vector и централизованный сбор логов', 'task': 'Настрой **log shipping**: Fluent Bit / Fluentd / Vector читает stdout (JSON), отправляет в Elasticsearch/Loki/CloudWatch. Покажи centralized logging architecture.', 'theory': 'Современные Go-приложения в контейнерах Kubernetes не знают об Elasticsearch или Loki. Они пишут чистый JSON в `os.Stdout`. Инфраструктурный DaemonSet-агент (Fluent Bit / Vector) вычитывает stdout контейнеров, парсит JSON, обогащает метаданными пода (`k8s.pod_name`, `k8s.namespace`) и асинхронно отправляет в хранилище.', 'step_by_step': '1. Сформируем идеальный Cloud-Native JSON логгер в Go.\n2. Продемонстрируем формат вывода для парсера Fluent Bit.\n3. Опишем архитектурную схему Log Shipping конвейера.\n4. В `main` выведем запись.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\t// Стандарт Cloud-Native 12-Factor App: вывод строго в os.Stdout\n\thandler := slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{\n\t\tLevel: slog.LevelInfo,\n\t})\n\tlogger := slog.New(handler)\n\n\tlogger.Info("Order placed successfully",\n\t\tslog.String("service", "checkout-service"),\n\t\tslog.String("version", "v2.14.0"),\n\t\tslog.Int64("order_id", 998811),\n\t\tslog.String("currency", "RUB"),\n\t\tslog.Float64("total", 4590.00),\n\t)\n\n\tfmt.Println("\\n=== Архитектура Log Shipping Конвейера ===")\n\tfmt.Println("1. Go App -> stdout (JSON Stream)")\n\tfmt.Println("2. Kubernetes Node -> /var/log/pods/*.log")\n\tfmt.Println("3. Fluent Bit / Vector DaemonSet -> вычитка, фильтрация, обогащение K8s тегами")\n\tfmt.Println("4. Ingestion Pipeline -> Kafka / Vector Aggregator")\n\tfmt.Println("5. Storage & Visualizer -> Grafana Loki / Elasticsearch + Kibana")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Order placed successfully","service":"checkout-service","version":"v2.14.0","order_id":998811,"currency":"RUB","total":4590}\n# \n# === Архитектура Log Shipping Конвейера ===\n# 1. Go App -> stdout (JSON Stream)\n# 2. Kubernetes Node -> /var/log/pods/*.log\n# 3. Fluent Bit / Vector DaemonSet -> вычитка, фильтрация, обогащение K8s тегами\n# 4. Ingestion Pipeline -> Kafka / Vector Aggregator\n# 5. Storage & Visualizer -> Grafana Loki / Elasticsearch + Kibana'}], 'under_the_hood': 'Vector и Fluent Bit написаны на Rust/C и потребляют всего 15–30 МБ RAM на ноду Kubernetes, обрабатывая сотни тысяч логов в секунду.', 'pitfalls': 'Не пишите ANSI-цвета терминала в stdout в production-режиме, так как ESC-последовательности ломают JSON-парсер Fluent Bit.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему запись логов напрямую по HTTP/TCP в Elasticsearch из Go сервиса считается антипаттерном?»\n**Ответ:** При сбое сети или перегрузке Elasticsearch сервис либо заблокируется, либо начнет терять логи. Схема через `stdout -> Fluent Bit` полностью изолирует приложение от отказов хранилища логов.'}, {'num': 35, 'title': 'Агрегация и фильтрация логов в Grafana Loki с помощью LogQL', 'task': 'Настрой **Loki** (Grafana): `logql` query `{job="order-service"} |= "error" | json | status_code >= 500`. Покажи log aggregation без full-text index (label-based).', 'theory': 'Grafana Loki использует подход Label-Based Indexing: индексируются только лейблы потока (`job`, `namespace`, `pod`), а само тело лога сжимается блоками в Chunks (S3/MinIO). Язык LogQL фильтрует и парсит JSON на лету во время выполнения запроса.', 'step_by_step': '1. Сформируем JSON-логи, соответствующие лейблам сервиса.\n2. Продемонстрируем синтаксис LogQL запроса.\n3. Разберем работу операторов `|=`, `| json`, `| status_code >= 500`.\n4. В `main` сымитируем фильтрацию логов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\t// Имитация записей микросервиса order-service\n\tlogger.Error("Database query failed",\n\t\tslog.String("job", "order-service"),\n\t\tslog.Int("status_code", 500),\n\t\tslog.String("db_error", "connection pool exhausted"),\n\t)\n\n\tfmt.Println("\\n=== Синтаксис LogQL для Grafana Loki ===")\n\tfmt.Println("Запрос:")\n\tfmt.Println(`  {job="order-service"} |= "Database" | json | status_code >= 500`)\n\tfmt.Println("\\nМеханика исполнения:")\n\tfmt.Println("  1. {job=\\"order-service\\"} — поиск чанков по индексу лейблов")\n\tfmt.Println("  2. |= \\"Database\\" — быстрый потоковый grep в памяти")\n\tfmt.Println("  3. | json — динамический парсинг JSON-полей")\n\tfmt.Println("  4. | status_code >= 500 — числовая фильтрация результата")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"Database query failed","job":"order-service","status_code":500,"db_error":"connection pool exhausted"}\n# \n# === Синтаксис LogQL для Grafana Loki ===\n# Запрос:\n#   {job="order-service"} |= "Database" | json | status_code >= 500\n# \n# Механика исполнения:\n#   1. {job="order-service"} — поиск чанков по индексу лейблов\n#   2. |= "Database" — быстрый потоковый grep в памяти\n#   3. | json — динамический парсинг JSON-полей\n#   4. | status_code >= 500 — числовая фильтрация результата'}], 'under_the_hood': 'Loki сжимает логи алгоритмом Snappy в блоках по 1.5MB, достигая степени сжатия 5:1 к исходному объему текста.', 'pitfalls': 'Не делайте `userID` или `requestID` лейблами в Loki — это вызовет High Cardinality взрыв индекса! Используйте их как обычные JSON поля.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему Grafana Loki в 10 раз дешевле Elasticsearch по ресурсам?»\n**Ответ:** Elasticsearch строит инвертированный индекс по каждому слову текста, потребляя гигабайты RAM. Loki индексирует только несколько тегов (namespace, app), сохраняя сырые данные в дешевом объектном хранилище S3.'}, {'num': 36, 'title': 'Метрики на основе логов: алертинг по росту частоты ошибок (Log-Based Metrics)', 'task': 'Создай **log-based metrics**: `count_over_time({job="order-service"} |= "payment_failed" [5m])`. Alert на рост ошибок без application metrics. Покажи dual signal.', 'theory': 'Log-Based Metrics превращают поток логов в числовые временные ряды (Prometheus Metrics). Функция `count_over_time(...[5m])` подсчитывает количество совпадений за 5-минутное окно для триггера алертов в Alertmanager.', 'step_by_step': '1. Запишем события неуспешных платежей.\n2. Продемонстрируем LogQL метрику `sum(rate({app="checkout"} |= "payment_failed" [1m]))`.\n3. Опишем правило алерта для Prometheus/Loki.\n4. В `main` выведем структуру метрик.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\tlogger.Warn("payment_failed: insufficient funds",\n\t\tslog.String("job", "order-service"),\n\t\tslog.String("user_id", "u-1092"),\n\t\tslog.String("reason", "LOW_BALANCE"),\n\t)\n\n\tfmt.Println("\\n=== Log-Based Metric Rule (Grafana / Prometheus) ===")\n\tfmt.Println("LogQL Metric Expression:")\n\tfmt.Println(`  sum by (reason) (count_over_time({job="order-service"} |= "payment_failed" | json [5m]))`)\n\tfmt.Println("\\nPrometheus Alert Rule:")\n\tfmt.Println("  alert: HighPaymentFailureRate")\n\tfmt.Println("  expr: sum(rate({job=\\"order-service\\"} |= \\"payment_failed\\" [5m])) > 10")\n\tfmt.Println("  for: 2m")\n\tfmt.Println("  labels: severity = critical")\n\tfmt.Println("  annotations: summary = \\"Обнаружен аномальный рост сбоев платежей (>10 ops/sec)\\"")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"WARN","msg":"payment_failed: insufficient funds","job":"order-service","user_id":"u-1092","reason":"LOW_BALANCE"}\n# \n# === Log-Based Metric Rule (Grafana / Prometheus) ===\n# LogQL Metric Expression:\n#   sum by (reason) (count_over_time({job="order-service"} |= "payment_failed" | json [5m]))\n# \n# Prometheus Alert Rule:\n#   alert: HighPaymentFailureRate\n#   expr: sum(rate({job="order-service"} |= "payment_failed" [5m])) > 10\n#   for: 2m\n#   labels: severity = critical\n#   annotations: summary = [Обнаружен аномальный рост сбоев платежей]\n'}], 'under_the_hood': 'Log-based метрики позволяют создавать алерты для legacy-систем и сторонних бинарников без необходимости внедрения Prometheus SDK в исходный код.', 'pitfalls': 'Log-based метрики создают дополнительную нагрузку на парсер логов. Для критических SLA используйте прямые `prometheus.Counter` в коде.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое Dual Signal в Observability?»\n**Ответ:** Совмещение двух сигналов мониторинга: Метрика фиксирует факт аномалии (рост ошибки на 300%), а прикрепленный Трейс/Лог дает точную причину сбоя со стек-трейсом.'}, {'num': 37, 'title': 'Перенаправление стандартного log.SetOutput в файл', 'task': 'Перенаправьте вывод стандартного `log` в файл вместо консоли с помощью `os.OpenFile` и `log.SetOutput`.', 'theory': 'Функция `log.SetOutput(w io.Writer)` перенаправляет поток вывода глобального стандартного логгера Go в любой объект, реализующий интерфейс `io.Writer` (например, файловый дескриптор `*os.File`).', 'step_by_step': '1. Откроем файл `service.log` в режиме `os.O_CREATE|os.O_WRONLY|os.O_APPEND`.\n2. Вызовем `log.SetOutput(file)`.\n3. Запишем несколько логов через `log.Println`.\n4. Прочитаем и проверим содержимое файла.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tlogPath := "service.log"\n\n\tfile, err := os.OpenFile(logPath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)\n\tif err != nil {\n\t\tlog.Fatalf("Ошибка открытия файла: %v", err)\n\t}\n\tdefer func() {\n\t\tfile.Close()\n\t\t_ = os.Remove(logPath)\n\t}()\n\n\t// Перенаправление стандартного логгера в файл\n\tlog.SetOutput(file)\n\n\tlog.Println("Инициализация сервиса авторизации")\n\tlog.Printf("Подключение к БД PostgreSQL: порт %d", 5432)\n\n\t// Проверяем данные на диске\n\tdata, _ := os.ReadFile(logPath)\n\tfmt.Println("--- Данные успешно записаны в файл service.log ---")\n\tfmt.Print(string(data))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Данные успешно записаны в файл service.log ---\n# 2026/09/02 18:40:00 Инициализация сервиса авторизации\n# 2026/09/02 18:40:00 Подключение к БД PostgreSQL: порт 5432'}], 'under_the_hood': '`log.SetOutput` защищен внутренним `sync.Mutex` стандартного пакета `log`, что делает смену вывода потокобезопасной.', 'pitfalls': 'Не закрывайте `file` до тех пор, пока работают горутины, пишущие в стандартный логгер, иначе возникнет паника `write on closed file`.', 'bigtech_interview': '**Вопрос с собеседования:** «Потокобезопасен ли стандартный пакет log при вызове log.Println из 1000 горутин?»\n**Ответ:** Да. Внутри стандартной структуры `log.Logger` каждая операция записи защищена мьютексом `l.mu.Lock()`, гарантируя целостность строк без перемешивания байтов.'}, {'num': 38, 'title': 'Информационные сообщения стандартного пакета log с автоматическим таймстемпом', 'task': 'Используйте стандартный пакет `log` для вывода информационного сообщения с автоматическим добавлением даты и времени.', 'theory': 'Стандартный пакет `log` по умолчанию добавляет локальную дату и время в формате `YYYY/MM/DD HH:MM:SS` к началу каждой строки сообщения и выводит результат в поток `os.Stderr`.', 'step_by_step': '1. Импортируем стандартный пакет `log`.\n2. Вызовем `log.Println("Сервис мониторинга успешно запущен")`.\n3. Вызовем `log.Printf("Слушатель открыт на порту :%d", 8080)`.\n4. В `main` убедимся в автоматическом добавлении даты и времени.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log"\n)\n\nfunc main() {\n\t// Базовый вывод со стандартным префиксом даты и времени\n\tlog.Println("Сервис мониторинга успешно запущен")\n\tlog.Printf("Слушатель открыт на порту :%d", 8080)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод (в поток Stderr):\n# 2026/09/02 18:40:00 Сервис мониторинга успешно запущен\n# 2026/09/02 18:40:00 Слушатель открыт на порту :8080'}], 'under_the_hood': 'Стандартный логгер использует неявный глобальный инстанс `std = New(os.Stderr, "", LstdFlags)`.', 'pitfalls': 'Вывод `log.Println` по умолчанию идет в `os.Stderr`, а не в `os.Stdout`! При фильтрации в bash `cmd > out.txt` логи останутся в терминале.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему стандартный пакет log в Go пишет в os.Stderr, а не в os.Stdout?»\n**Ответ:** Чтобы не смешивать системные логи сервиса с полезным потоком данных (Payload / CLI Output) программы, который передается по Unix-пайпу `stdout | next_cmd`.'}, {'num': 39, 'title': 'Базовые методы log.Println и log.Printf стандартного логгера', 'task': '**Стандартный логгер**: Напишите программу, которая использует стандартный пакет `log` для вывода информационных сообщений (`log.Println`, `log.Printf`). Обратите внимание на формат вывода по умолчанию (дата и время).', 'theory': '`log.Println` форматирует аргументы через пробел и добавляет перевод строки `\\n`. `log.Printf` форматирует строку по спецификаторам `%s`, `%d`, `%v` и автоматически добавляет `\\n`, если его нет в конце формата.', 'step_by_step': '1. Вызовем `log.Println` с несколькими аргументами.\n2. Вызовем `log.Printf` с форматированными числами и строками.\n3. Проверим структуру лога.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log"\n)\n\nfunc main() {\n\tuser := "admin"\n\tactiveConnections := 142\n\n\t// log.Println автоматически добавляет пробелы между аргументами\n\tlog.Println("Аудит безопасности:", "пользователь", user, "выполнил вход")\n\n\t// log.Printf поддерживает форматирование по шаблону\n\tlog.Printf("Статистика пула соединений: active=%d limit=%d usage=%.1f%%",\n\t\tactiveConnections, 200, float64(activeConnections)/200.0*100)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 2026/09/02 18:40:00 Аудит безопасности: пользователь admin выполнил вход\n# 2026/09/02 18:40:00 Статистика пула соединений: active=142 limit=200 usage=71.0%'}], 'under_the_hood': '`log.Printf` оборачивает вызов в `fmt.Sprintf` внутри критической секции мьютекса `l.mu.Lock()`.', 'pitfalls': 'В отличие от `fmt.Printf`, `log.Printf` автоматически добавляет символ `\\n` в конец строки, если разработчик забыл его указать.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие log.Printf от log.Println по производительности?»\n**Ответ:** `log.Printf` требует синтаксического разбора шаблона форматирования (парсинг `%`), тогда как `log.Println` выполняет прямую конкатенацию строковых представлений аргументов.'}, {'num': 40, 'title': 'Сравнение логики работы log.Println и fmt.Println', 'task': '**Базовый `log`**: Используй пакет `log`. Вызови `log.Println` и `log.Printf`. Сравни их вывод с `fmt.Println` (логи по умолчанию добавляют дату и время).', 'theory': '`fmt.Println` пишет "сырой" текст в `os.Stdout` без метаданных и без синхронизации горутин. `log.Println` пишет в `os.Stderr`, добавляет метку времени и защищает запись мьютексом.', 'step_by_step': '1. Вызовем `fmt.Println("Сообщение через fmt")`.\n2. Вызовем `log.Println("Сообщение через log")`.\n3. Сравним потоки вывода и наличие префиксов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n)\n\nfunc main() {\n\tmsg := "Инициализация подсистемы кэширования"\n\n\t// 1. Прямой вывод без метаданных в os.Stdout\n\tfmt.Println("[fmt.Println] ->", msg)\n\n\t// 2. Логирование с таймстемпом в os.Stderr\n\tlog.Println("[log.Println] ->", msg)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [fmt.Println] -> Инициализация подсистемы кэширования\n# 2026/09/02 18:40:00 [log.Println] -> Инициализация подсистемы кэширования'}], 'under_the_hood': '`log.Println` форматирует таймстемп в локальный буфер `[]byte`, минимизируя нагрузку на сборщик мусора.', 'pitfalls': 'Использование `fmt.Println` в многопоточном сервисе может приводить к чередованию и разрыву строк (Data Interleaving), так как `fmt` не использует мьютексы.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в продакшене линтер запрещает вызовы fmt.Println / fmt.Printf?»\n**Ответ:** 1) `fmt` не потокобезопасен (строки логов перемешиваются). 2) `fmt` не содержит таймстемпа и уровня логов. 3) `fmt` невозможно централизованно перенаправить в JSON-файл или систему сбора логов.'}, {'num': 41, 'title': 'Потокобезопасность и атомарность вывода: log vs fmt', 'task': 'Сравни вывод `log.Println` и `fmt.Println` (обрати внимание на автоматическую простановку даты и времени в `log`).', 'theory': 'При одновременной записи из 100 горутин вызовы `fmt.Print` могут перемешивать фрагменты разных строк на терминале. Вызовы `log.Println` атомарны: каждая строка пишется целиком за один вызов системного `write(2)` под мьютексом.', 'step_by_step': '1. Запустим несколько горутин с `fmt.Println`.\n2. Запустим аналогичные горутины с `log.Println`.\n3. Убедимся в целостности строк `log.Println`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"sync"\n)\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\n\tfmt.Println("--- Тестирование атомарности log.Println ---")\n\tfor i := 1; i <= 3; i++ {\n\t\twg.Add(1)\n\t\tgo func(workerID int) {\n\t\t\tdefer wg.Done()\n\t\t\tlog.Printf("Воркер #%d выполнил расчет хеша", workerID)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Тестирование атомарности log.Println ---\n# 2026/09/02 18:40:00 Воркер #1 выполнил расчет хеша\n# 2026/09/02 18:40:00 Воркер #2 выполнил расчет хеша\n# 2026/09/02 18:40:00 Воркер #3 выполнил расчет хеша'}], 'under_the_hood': '`log.Logger` захватывает внутренний мьютекс `l.mu.Lock()` перед генерацией строки и освобождает `l.mu.Unlock()` строго после завершения `w.Write()`.', 'pitfalls': 'Блокировка мьютекса в `log.Logger` при медленном диске может стать узким местом для сотен тысяч горутин.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова сложность захвата мьютекса в log.Logger при отсутствии конкуренции?»\n**Ответ:** В современных процессорах неконкурентный захват мьютекса выполняется за ~10-15 наносекунд через быструю атомарную инструкцию `CMPXCHG` (CAS).'}, {'num': 42, 'title': 'Перенаправление потока логирования в файл app.log через log.SetOutput', 'task': '**Смена вывода (Output)**: Открой файл `app.log`. Используй `log.SetOutput(file)`, чтобы перенаправить все логи из консоли в файл. Запиши пару логов и проверь файл.', 'theory': '`log.SetOutput(file)` подменяет внутренний дескриптор `os.Stderr` на открытый файл. Все последующие вызовы `log.Println` во всей программе будут направлены в файл на диске.', 'step_by_step': '1. Создадим файл `app.log` в режиме дозаписи.\n2. Вызовем `log.SetOutput(f)`.\n3. Запишем информационные логи.\n4. Прочитаем файл и выведем его в консоль.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "app.log"\n\tfile, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)\n\tif err != nil {\n\t\tlog.Fatalf("Ошибка открытия лог-файла: %v", err)\n\t}\n\tdefer func() {\n\t\tfile.Close()\n\t\t_ = os.Remove(path)\n\t}()\n\n\t// Перенаправление стандартного логгера\n\tlog.SetOutput(file)\n\n\tlog.Println("[INFO] Приложение успешно запустилось")\n\tlog.Println("[WARN] Низкий свободный объем кэша Redis")\n\n\t// Проверка файла\n\tdata, _ := os.ReadFile(path)\n\tfmt.Println("--- Проверка файла app.log на диске ---")\n\tfmt.Print(string(data))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Проверка файла app.log на диске ---\n# 2026/09/02 18:40:00 [INFO] Приложение успешно запустилось\n# 2026/09/02 18:40:00 [WARN] Низкий свободный объем кэша Redis'}], 'under_the_hood': '`os.OpenFile` с флагом `os.O_APPEND` заставляет ядро ОС автоматически позиционировать курсор в конец файла перед каждым системным вызовом `write(2)`.', 'pitfalls': 'Если забыть флаг `os.O_APPEND` при перезапуске программы, файл будет перезаписан с начала, уничтожив старые логи.', 'bigtech_interview': '**Вопрос с собеседования:** «Безопасно ли вызывать log.SetOutput во время работы других горутин?»\n**Ответ:** Да, функция `log.SetOutput` потокобезопасна, так как захватывает внутренний `sync.Mutex` логгера перед заменой `io.Writer`.'}, {'num': 43, 'title': 'Логирование запуска сервера со стандартным таймстемпом', 'task': 'Используй `log.Println("Server started")`. Покажи, что по умолчанию выводится с timestamp.', 'theory': 'По умолчанию флаги стандартного логгера установлены в `log.LstdFlags` (комбинация `log.Ldate | log.Ltime`). Это гарантирует наличие временной метки `2026/09/02 18:40:00`.', 'step_by_step': '1. Вызовем `log.Println("Server started on port :8080")`.\n2. Зафиксируем структуру формата даты и времени.\n3. В `main` убедимся в наличии таймстемпа.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log"\n)\n\nfunc main() {\n\t// Дефолтный вызов standard library logger\n\tlog.Println("Server started")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 2026/09/02 18:40:00 Server started'}], 'under_the_hood': 'Таймстемп вычисляется через `time.Now()` в момент вызова метода `Output`.', 'pitfalls': 'Таймстемп стандартного логгера использует локальный часовой пояс сервера, что может вызвать путаницу при синхронизации логов из разных дата-центров. Для UTC используйте `log.LUTC`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как включить вывод таймстемпов в UTC в стандартном пакете log?»\n**Ответ:** Установить флаг `log.LUTC`: `log.SetFlags(log.LstdFlags | log.LUTC)`.'}, {'num': 44, 'title': 'Настройка флагов логгера: микросекунды и имя файла через log.SetFlags', 'task': '**Настройка флагов логгера**: Используя функцию `log.SetFlags`, настройте стандартный логгер так, чтобы он выводил микросекунды, а также имя файла и номер строки, где был вызван лог (флаги `log.Lmicroseconds`, `log.Lshortfile`).', 'theory': 'Битовая маска флагов `log.SetFlags` позволяет кастомизировать префикс логов: `log.Ldate` (дата), `log.Ltime` (время), `log.Lmicroseconds` (микросекунды) и `log.Lshortfile` (`main.go:24`).', 'step_by_step': '1. Скомбинируем флаги: `log.Ldate | log.Ltime | log.Lmicroseconds | log.Lshortfile`.\n2. Применим через `log.SetFlags(...)`.\n3. Запишем тестовый лог.\n4. В `main` убедимся в отображении микросекунд и номера строки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log"\n)\n\nfunc main() {\n\t// Настройка флагов: дата + время с микросекундами + короткое имя файла и строка\n\tlog.SetFlags(log.Ldate | log.Ltime | log.Lmicroseconds | log.Lshortfile)\n\n\tlog.Println("Инициализация высокоточного таймера")\n\tlog.Println("Соединение с брокером сообщений установлено")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 2026/09/02 18:40:00.194821 main.go:11: Инициализация высокоточного таймера\n# 2026/09/02 18:40:00.194899 main.go:12: Соединение с брокером сообщений установлено'}], 'under_the_hood': '`log.Lshortfile` вызывает `runtime.Caller(calldepth)` и отсекает родительские директории пути через `strings.LastIndex`.', 'pitfalls': 'Флаг `log.Llongfile` выводит полный абсолютный путь к файлу `/home/ut/work/go-workout/main.go:11`, что сильно удлиняет строки.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие log.Lshortfile от log.Llongfile?»\n**Ответ:** `log.Lshortfile` выводит только имя файла и строку (`server.go:42`), а `log.Llongfile` — полный абсолютный путь в файловой системе (`/app/pkg/api/server.go:42`).'}, {'num': 45, 'title': 'Сравнение различных комбинаций флагов стандартного пакета log', 'task': 'Настрой флаги логгера: `log.SetFlags(log.LstdFlags | log.Lshortfile | log.Lmicroseconds)`. Покажи разницу в выводе (файл, строка, микросекунды).', 'theory': 'Комбинирование битовых флагов через побитовое ИЛИ (`|`) формирует требуемый набор метаданных лога.', 'step_by_step': '1. Выведем лог с `log.LstdFlags`.\n2. Установим `log.LstdFlags | log.Lshortfile | log.Lmicroseconds`.\n3. Выведем лог и сравним форматы.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n)\n\nfunc main() {\n\t// 1. Стандартные флаги (Дата + Время)\n\tlog.SetFlags(log.LstdFlags)\n\tfmt.Println("=== 1. Стандартный вывод ===")\n\tlog.Println("Лог со стандартными флагами")\n\n\t// 2. Расширенные флаги (+ микросекунды + файл и строка)\n\tlog.SetFlags(log.LstdFlags | log.Lshortfile | log.Lmicroseconds)\n\tfmt.Println("\\n=== 2. Расширенный вывод (Микросекунды + Файл:Строка) ===")\n\tlog.Println("Лог с расширенными флагами")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === 1. Стандартный вывод ===\n# 2026/09/02 18:40:00 Лог со стандартными флагами\n# \n# === 2. Расширенный вывод (Микросекунды + Файл:Строка) ===\n# 2026/09/02 18:40:00.849201 main.go:17: Лог с расширенными флагами'}], 'under_the_hood': '`log.LstdFlags` эквивалентен константе `log.Ldate | log.Ltime` (значение `3`).', 'pitfalls': 'Если передать флаг `0` (`log.SetFlags(0)`), логгер не будет выводить дату, время и имя файла, печатая только чистый текст.', 'bigtech_interview': '**Вопрос с собеседования:** «Как полностью убрать префикс даты и времени в log?»\n**Ответ:** Вызвать `log.SetFlags(0)`. Логгер будет выводить только переданный текст без префиксов времени.'}, {'num': 46, 'title': 'Аварийное завершение процесса через log.Fatalf с кодом 1', 'task': 'Вызови `log.Fatalf("Fatal error: %v", err)`. Убедись, что программа завершается с кодом 1 после записи лога.', 'theory': '`log.Fatalf` записывает форматированное сообщение в лог и немедленно завершает работу всей программы вызовом `os.Exit(1)`. При этом ни один зарегистрированный оператор `defer` **не выполняется**.', 'step_by_step': '1. Зарегистрируем отложенный вызов `defer fmt.Println("Этот defer НЕ выполнится!")`.\n2. Запишем лог через `log.Fatalf(...)`.\n3. Убедимся, что процесс завершился с кодом 1.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"log"\n)\n\nfunc main() {\n\tdefer fmt.Println("[DEFER] Этот код никогда не выполнится из-за os.Exit(1)")\n\n\terr := errors.New("порт 8080 уже занят другим процессом")\n\n\tlog.Println("[INFO] Попытка запуска HTTP-сервера...")\n\tlog.Fatalf("Критический сбой инициализации: %v", err)\n\n\tfmt.Println("Этот код также недостижим")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 2026/09/02 18:40:00 [INFO] Попытка запуска HTTP-сервера...\n# 2026/09/02 18:40:00 Критический сбой инициализации: порт 8080 уже занят другим процессом\n# exit status 1'}], 'under_the_hood': '`log.Fatalf` внутри выполняет `l.Output(2, fmt.Sprintf(format, v...))` и затем вызывает `os.Exit(1)`.', 'pitfalls': 'Никогда не используйте `log.Fatal` внутри библиотечных пакетов или вспомогательных функций — фатальный выход разрешен только в функции `main()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему вызов log.Fatal в HTTP-обработчике является грубейшей ошибкой?»\n**Ответ:** Потому что `log.Fatal` не просто прерывает обработку одного HTTP-запроса, а мгновенно роняет весь веб-сервер и все параллельно выполняющиеся запросы тысяч пользователей.'}, {'num': 47, 'title': 'Настройка JSON-формата slog для облачных сред ELK и Grafana Loki', 'task': 'Настройте `slog` для вывода в формате JSON (через `slog.NewJSONHandler`), что является стандартом для облачных приложений и сбора логов (ELK, Loki).', 'theory': 'Вывод в JSON — фундаментальное требование для сбора логов в облачных средах (Kubernetes, AWS EKS, Yandex Cloud). JSON позволяет индексировать поля в Elasticsearch, OpenSearch и Grafana Loki.', 'step_by_step': '1. Создадим `slog.NewJSONHandler(os.Stdout, nil)`.\n2. Обернем в `slog.New(handler)`.\n3. Установим дефолтным через `slog.SetDefault(logger)`.\n4. Запишем событие с контекстом окружения `env`, `service`, `version`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\t// Инициализация стандартного JSON-хендлера для Cloud-Native\n\tjsonHandler := slog.NewJSONHandler(os.Stdout, nil)\n\tlogger := slog.New(jsonHandler)\n\tslog.SetDefault(logger)\n\n\tslog.Info("Микросервис успешно развернут в кластере",\n\t\tslog.String("service.name", "billing-gateway"),\n\t\tslog.String("service.version", "v1.8.4"),\n\t\tslog.String("environment", "production"),\n\t\tslog.String("k8s.pod_name", "billing-gateway-7d89f4b-2kz8w"),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Микросервис успешно развернут в кластере","service.name":"billing-gateway","service.version":"v1.8.4","environment":"production","k8s.pod_name":"billing-gateway-7d89f4b-2kz8w"}'}], 'under_the_hood': '`slog.NewJSONHandler` использует буферизованный кодировщик с экранированием спецсимволов UTF-8 по стандарту RFC 8259.', 'pitfalls': 'Не перегружайте каждую запись статическими полями `service.name` вручную — добавьте их один раз при старте через `logger.With(...)`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как в slog один раз добавить глобальные поля окружения (service, env, version) ко всем логам приложения?»\n**Ответ:** Создать логгер через `logger := slog.New(handler).With("service", "auth", "env", "prod")` и установить его через `slog.SetDefault(logger)`.'}, {'num': 48, 'title': 'Создание изолированного логгера log.New с префиксом и записью в файл', 'task': 'Создай логгер, пишущий в файл: `f, _ := os.Create("app.log"); logger := log.New(f, "APP: ", log.LstdFlags)`. Пиши через `logger.Println`. Проверь файл.', 'theory': 'Функция `log.New(out, prefix, flag)` создает изолированный экземпляр `*log.Logger`. Это предотвращает конфликт префиксов и потоков вывода между независимыми модулями приложения.', 'step_by_step': '1. Создадим файл `app_custom.log`.\n2. Инициализируем `appLogger := log.New(f, "APP: ", log.LstdFlags)`.\n3. Запишем строки через `appLogger.Println`.\n4. В `main` проверим содержимое файла.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "app_custom.log"\n\tf, err := os.Create(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer func() {\n\t\tf.Close()\n\t\t_ = os.Remove(path)\n\t}()\n\n\t// Создаем выделенный экземпляр логгера для модуля APP\n\tappLogger := log.New(f, "APP: ", log.LstdFlags)\n\n\tappLogger.Println("Старт процесса обработки фоновых задач")\n\tappLogger.Println("Обработано 150 элементов очереди")\n\n\tdata, _ := os.ReadFile(path)\n\tfmt.Println("--- Содержимое файла app_custom.log ---")\n\tfmt.Print(string(data))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Содержимое файла app_custom.log ---\n# APP: 2026/09/02 18:40:00 Старт процесса обработки фоновых задач\n# APP: 2026/09/02 18:40:00 Обработано 150 элементов очереди'}], 'under_the_hood': 'Префикс `"APP: "` конкатенируется перед датой и временем в буфере строки лога.', 'pitfalls': 'Если не закрыть файл `f.Close()` перед выходом, буфер ОС может не успеть записать последние байты на диск.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему создание собственных инстансов *log.Logger лучше использования глобального пакета log?»\n**Ответ:** Глобальное состояние (Package-level state) затрудняет тестирование, не позволяет настроить разные префиксы для модулей и создает неявные зависимости между пакетами.'}, {'num': 49, 'title': 'Мультиплексирование вывода через io.MultiWriter: консоль и файл', 'task': 'Используйте `io.MultiWriter`, чтобы логировать сообщения **одновременно** в консоль (`os.Stdout`) и в файл.', 'theory': '`io.MultiWriter` объединяет несколько потоков `io.Writer` в единый интерфейс. Каждая операция `Write` дублируется во все зарегистрированные приемники.', 'step_by_step': '1. Создадим файл `multi_dest.log`.\n2. Создадим `mw := io.MultiWriter(os.Stdout, file)`.\n3. Создадим логгер `logger := log.New(mw, "[SERVICE] ", log.LstdFlags)`.\n4. Запишем лог и убедимся в появлении текста и в консоли, и в файле.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "multi_dest.log"\n\tfile, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer func() {\n\t\tfile.Close()\n\t\t_ = os.Remove(path)\n\t}()\n\n\t// Мультиплексирование потоков: Stdout + File\n\tmultiWriter := io.MultiWriter(os.Stdout, file)\n\tdualLogger := log.New(multiWriter, "[SERVICE] ", log.Ldate|log.Ltime)\n\n\tfmt.Println("=== Вывод в консоль во время работы ===")\n\tdualLogger.Println("HTTP-сервер запущен на :9000")\n\tdualLogger.Println("Подключение к Redis успешно")\n\n\tfileData, _ := os.ReadFile(path)\n\tfmt.Println("\\n=== Проверка содержимого файла на диске ===")\n\tfmt.Print(string(fileData))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === Вывод в консоль во время работы ===\n# [SERVICE] 2026/09/02 18:40:00 HTTP-сервер запущен на :9000\n# [SERVICE] 2026/09/02 18:40:00 Подключение к Redis успешно\n# \n# === Проверка содержимого файла на диске ===\n# [SERVICE] 2026/09/02 18:40:00 HTTP-сервер запущен на :9000\n# [SERVICE] 2026/09/02 18:40:00 Подключение к Redis успешно'}], 'under_the_hood': '`io.MultiWriter` выполняет синхронные вызовы `w.Write(p)` в цикле по списку писателей.', 'pitfalls': 'Если один из писателей вернет ошибку (например, кончилось место на диске), `MultiWriter` прервет цикл и не запишет данные в оставшиеся потоки.', 'bigtech_interview': '**Вопрос с собеседования:** «Как сделать так, чтобы ошибка записи в файл не ломала вывод в stdout при использовании io.MultiWriter?»\n**Ответ:** Реализовать собственный безопасный мульти-писатель (SafeMultiWriter), который игнорирует ошибки отдельных приемников или логирует их в `os.Stderr` без прерывания цикла.'}, {'num': 50, 'title': 'Перенаправление логов в файл app.log в режиме дозаписи', 'task': '**Логирование в файл**: Напишите код, который открывает файл `app.log` на дозапись. Перенаправьте вывод стандартного логгера в этот файл с помощью `log.SetOutput(file)`. Сделайте тестовую запись и убедитесь, что логи пишутся на диск, а не в консоль.', 'theory': 'Режим `os.O_APPEND` гарантирует, что каждая новая запись добавляется в конец файла без затирания истории работы сервиса.', 'step_by_step': '1. Откроем `app.log` с флагами `os.O_CREATE|os.O_WRONLY|os.O_APPEND`.\n2. Применим `log.SetOutput(file)`.\n3. Запишем 2 строки.\n4. Проверим чтением с диска.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "app_append.log"\n\n\t// Открытие на дозапись\n\tfile, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)\n\tif err != nil {\n\t\tlog.Fatalf("Ошибка открытия файла: %v", err)\n\t}\n\tdefer func() {\n\t\tfile.Close()\n\t\t_ = os.Remove(path)\n\t}()\n\n\tlog.SetOutput(file)\n\n\tlog.Println("[INFO] Сессия пользователя 101 открыта")\n\tlog.Println("[INFO] Сессия пользователя 101 закрыта")\n\n\tdata, _ := os.ReadFile(path)\n\tfmt.Println("--- Данные успешно сохранены в app_append.log ---")\n\tfmt.Print(string(data))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Данные успешно сохранены в app_append.log ---\n# 2026/09/02 18:40:00 [INFO] Сессия пользователя 101 открыта\n# 2026/09/02 18:40:00 [INFO] Сессия пользователя 101 закрыта'}], 'under_the_hood': 'Системный вызов Linux `open(path, O_CREAT|O_WRONLY|O_APPEND, 0644)` гарантирует атомарную дозапись на уровне файловой системы.', 'pitfalls': 'В Windows при открытии файла другими процессами без флага общего доступа (Share Mode) может возникнуть ошибка доступа.', 'bigtech_interview': '**Вопрос с собеседования:** «Могут ли два независимых процесса одновременно безопасно писать в один лог-файл с флагом O_APPEND в Linux?»\n**Ответ:** Да. В POSIX-совместимых ОС запись с флагом `O_APPEND` размером меньше `PIPE_BUF` (обычно 4096 байт) является атомарной на уровне ядра.'}, {'num': 51, 'title': 'Текстовое структурированное логирование slog.NewTextHandler', 'task': 'Перейди на `log/slog` (Go 1.21+). Создай `slog.Logger` с `slog.NewTextHandler(os.Stdout, nil)`. Выведи структурированный лог: `slog.Info("user login", slog.String("user_id", "123"), slog.String("ip", "10.0.0.1"))`.', 'theory': '`slog.NewTextHandler` форматирует записи в human-readable формате `key=value` (формат logfmt). Он удобен для локальной разработки и отладки в терминале.', 'step_by_step': '1. Создадим `textHandler := slog.NewTextHandler(os.Stdout, nil)`.\n2. Обернем в `slog.New(textHandler)`.\n3. Запишем лог с типизированными атрибутами `slog.String`.\n4. В `main` убедимся в формате `time=... level=INFO msg=... key=val`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\t// Текстовый обработчик logfmt для локальной разработки\n\thandler := slog.NewTextHandler(os.Stdout, nil)\n\tlogger := slog.New(handler)\n\tslog.SetDefault(logger)\n\n\tslog.Info("user login",\n\t\tslog.String("user_id", "123"),\n\t\tslog.String("ip", "10.0.0.1"),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# time=2026-09-02T18:40:00.000Z level=INFO msg="user login" user_id=123 ip=10.0.0.1'}], 'under_the_hood': '`slog.TextHandler` оборачивает значения в кавычки `""`, только если они содержат пробелы или спецсимволы.', 'pitfalls': 'В проде используйте `NewJSONHandler`, а не `NewTextHandler`, так как парсинг logfmt в Kibana медленнее JSON.', 'bigtech_interview': '**Вопрос с собеседования:** «Как настроить автоматическое переключение TextHandler в DEV и JSONHandler в PROD?»\n**Ответ:** Проверять переменную окружения `ENV == "production"` при инициализации и выбирать `slog.NewJSONHandler` для продакшена и `slog.NewTextHandler` для локальной разработки.'}, {'num': 52, 'title': 'Фабрика логгеров с ежедневной сменой имени файла CreateDailyLogger', 'task': 'Напиши функцию `CreateDailyLogger() *log.Logger`, создающую лог-файл с датой в имени (`app_2026-07-03.log`). Используй `log.New`.', 'theory': 'Ежедневное разделение лог-файлов (Daily Rolling Logger) группирует логи по датам, упрощая поиск инцидентов и настройку политик архивации.', 'step_by_step': '1. Получим текущую дату `time.Now().Format("2006-01-02")`.\n2. Сформируем имя файла `fmt.Sprintf("app_%s.log", dateStr)`.\n3. Откроем файл на дозапись.\n4. Создадим и вернем `log.New(f, "[DAILY] ", log.LstdFlags)`.\n5. В `main` протестируем запись.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n\t"time"\n)\n\nfunc CreateDailyLogger() (*log.Logger, *os.File, error) {\n\tcurrentDate := time.Now().Format("2006-01-02")\n\tfileName := fmt.Sprintf("app_%s.log", currentDate)\n\n\tfile, err := os.OpenFile(fileName, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)\n\tif err != nil {\n\t\treturn nil, nil, err\n\t}\n\n\tlogger := log.New(file, "[DAILY] ", log.LstdFlags|log.Lshortfile)\n\treturn logger, file, nil\n}\n\nfunc main() {\n\tdailyLogger, file, err := CreateDailyLogger()\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer func() {\n\t\tfileName := file.Name()\n\t\tfile.Close()\n\t\t_ = os.Remove(fileName)\n\t}()\n\n\tdailyLogger.Println("Старт обработки ежедневной финансовой сверки")\n\tdailyLogger.Println("Сверка завершена: 0 расхождений")\n\n\tdata, _ := os.ReadFile(file.Name())\n\tfmt.Printf("--- Содержимое файла %s ---\\n", file.Name())\n\tfmt.Print(string(data))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Содержимое файла app_2026-09-02.log ---\n# [DAILY] 2026/09/02 18:40:00 main.go:30: Старт обработки ежедневной финансовой сверки\n# [DAILY] 2026/09/02 18:40:00 main.go:31: Сверка завершена: 0 расхождений'}], 'under_the_hood': 'Шаблон даты в Go `2006-01-02` (Mon Jan 2 15:04:05 MST 2006) — стандарт форматирования времени.', 'pitfalls': 'В долгоживущем процессе при наступлении полуночи необходимо переоткрывать файл на новую дату.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать ротацию Daily Logger ровно в 00:00:00 без перезапуска сервиса?»\n**Ответ:** Запустить фоновую горутину, которая рассчитывает задержку до следующей полуночи: `time.Until(tomorrowMidnight)`, засыпает на этот интервал через `time.Sleep` и атомарно подменяет дескриптор файла под мьютексом.'}, {'num': 53, 'title': 'Создание изолированного экземпляра log.New для безопасности модулей', 'task': '**Свой экземпляр `Logger`**: Вместо глобального `log`, создай свой инстанс: `myLog := log.New(os.Stdout, "APP: ", log.LstdFlags)`. Это безопаснее и чище.', 'theory': 'Использование собственных инстансов `*log.Logger` предотвращает сайд-эффекты от изменения глобального логгера сторонними библиотеками.', 'step_by_step': '1. Создадим структуру сервиса `type PaymentService struct { log *log.Logger }`.\n2. Внедрим логгер через конструктор.\n3. Вызовем бизнес-метод.\n4. В `main` убедимся в чистой архитектуре Dependency Injection.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log"\n\t"os"\n)\n\ntype PaymentService struct {\n\tlogger *log.Logger\n}\n\nfunc NewPaymentService(l *log.Logger) *PaymentService {\n\treturn &PaymentService{logger: l}\n}\n\nfunc (s *PaymentService) Charge(amount int) {\n\ts.logger.Printf("Списание средств: %d руб. успешно завершено", amount)\n}\n\nfunc main() {\n\t// Создаем независимый инстанс логгера\n\tmyLog := log.New(os.Stdout, "APP: ", log.LstdFlags)\n\n\tservice := NewPaymentService(myLog)\n\tservice.Charge(2500)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# APP: 2026/09/02 18:40:00 Списание средств: 2500 руб. успешно завершено'}], 'under_the_hood': 'Передача логгера через структуру следует принципу инверсии зависимостей (Dependency Injection).', 'pitfalls': 'Если передать `nil` в качестве логгера, вызов методов приведет к панике nil pointer dereference.', 'bigtech_interview': '**Вопрос с собеседования:** «Как в тестах заглушить логирование в структуре PaymentService?»\n**Ответ:** Передать логгер, пишущий в `io.Discard`: `log.New(io.Discard, "", 0)`. Это полностью отключит вывод в тестах с 0 аллокаций памяти.'}, {'num': 54, 'title': 'Фатальные ошибки: мгновенный os.Exit(1) и пропуск всех defer вызовов', 'task': 'Используй `log.Fatalf("Critical error: %v", err)` при фатальной ошибке. Покажи, что программа завершается с `os.Exit(1)` и `defer` не выполняются.', 'theory': '`log.Fatalf` вызывает системный вызов ядра `exit_group(2)`. Рантайм Go не раскручивает стек (no stack unwinding), поэтому операторы `defer` (закрытие соединений, коммит транзакций) не выполняются.', 'step_by_step': '1. Объявим несколько `defer` функций с очисткой ресурсов.\n2. Вызовем `log.Fatalf`.\n3. Убедимся, что ни один `defer` не сработал.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"log"\n)\n\nfunc runCriticalProcess() {\n\tdefer fmt.Println("[DEFER 1] Освобождение пула соединений")\n\tdefer fmt.Println("[DEFER 2] Сброс временных файлов")\n\n\terr := errors.New("не удалось подключиться к мастер-ноде БД")\n\n\tlog.Printf("[INFO] Инициализация кластера...")\n\t// log.Fatalf завершает процесс немедленно:\n\tlog.Fatalf("Critical error: %v", err)\n\n\tfmt.Println("Код после Fatalf")\n}\n\nfunc main() {\n\trunCriticalProcess()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 2026/09/02 18:40:00 [INFO] Инициализация кластера...\n# 2026/09/02 18:40:00 Critical error: не удалось подключиться к мастер-ноде БД\n# exit status 1'}], 'under_the_hood': '`os.Exit` немедленно передает управление ядру ОС, игнорируя отложенные функции в стеке вызовов.', 'pitfalls': 'Если вам нужно гарантированное закрытие ресурсов, возвращайте ошибку в `main()`, закрывайте ресурсы и вызывайте `os.Exit(1)` в самом конце `main`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как правильно завершать Go сервис при фатальных ошибках инициализации?»\n**Ответ:** Организовать функцию `run() error` внутри `main()`. Внутри `run()` использовать обычные возвраты `return fmt.Errorf(...)`. В `main()` вызвать `if err := run(); err != nil { log.Println(err); os.Exit(1) }`. Это гарантирует выполнение всех `defer` внутри `run()`.'}, {'num': 55, 'title': 'Реализация архитектуры Incident Response Workflow в SRE', 'task': 'Реализуй **Incident Response Workflow**:\n- Alert fires: `HighLatency p95 > 500ms`\n- Automated: create incident in PagerDuty, Slack channel `#incidents-2026-07-03`\n- Runbook: "1. Check Grafana dashboard. 2. Check recent deployments. 3. Check error logs."\n- Human: identify root cause (bad deployment), rollback\n- Post-mortem: timeline, root cause, action items, publish in Wiki\n- Metrics: MTTR (Mean Time To Recovery), MTBF (Mean Time Between Failures)', 'theory': 'Incident Response Workflow — стандарт управления инцидентами в BigTech (Google SRE, Яндекс, Ozon). При срабатывании алерта автоматика создает инцидент, инженер выполняет шаги по Runbook, организуется Rollback и формируется Post-Mortem.', 'step_by_step': '1. Создадим структуру `IncidentWorkflow`.\n2. Реализуем фазы: `TriggerAlert`, `CreateChannels`, `ExecuteRunbook`, `MitigateRollback`, `GeneratePostMortem`.\n3. В `main` смоделируем прохождение полного инцидента.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n\t"time"\n)\n\ntype Incident struct {\n\tID        string\n\tAlertName string\n\tStartTime time.Time\n\tEndTime   time.Time\n\tRootCause string\n}\n\nfunc (inc *Incident) Resolve(cause string) {\n\tinc.EndTime = time.Now()\n\tinc.RootCause = cause\n}\n\nfunc (inc *Incident) MTTR() time.Duration {\n\treturn inc.EndTime.Sub(inc.StartTime)\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\t// 1. Alert fires\n\tincident := Incident{\n\t\tID:        "INC-88912",\n\t\tAlertName: "HighLatency p95 > 500ms",\n\t\tStartTime: time.Now().Add(-12 * time.Minute),\n\t}\n\n\tlogger.Error("PAGERDUTY ALERT TRIGGERED",\n\t\tslog.String("incident_id", incident.ID),\n\t\tslog.String("alert", incident.AlertName),\n\t\tslog.String("slack_channel", "#incidents-2026-09-02"),\n\t)\n\n\t// 2. Runbook & Mitigation\n\tfmt.Println("\\n--- Runbook Checklist ---")\n\tfmt.Println(" [x] 1. Check Grafana dashboard (Latency spike detected)")\n\tfmt.Println(" [x] 2. Check recent deployments (v2.14.1 deployed 15m ago)")\n\tfmt.Println(" [x] 3. Check error logs (DB index missing)")\n\tfmt.Println(" [x] 4. Mitigation: Rollback to v2.14.0 executed")\n\n\t// 3. Resolution\n\tincident.Resolve("Bad deployment v2.14.1 (unindexed query)")\n\n\tlogger.Info("INCIDENT RESOLVED",\n\t\tslog.String("incident_id", incident.ID),\n\t\tslog.Duration("mttr", incident.MTTR()),\n\t\tslog.String("root_cause", incident.RootCause),\n\t)\n\n\t// 4. Post-Mortem Summary\n\tfmt.Println("\\n=== Post-Mortem Summary ===")\n\tfmt.Printf("Incident ID: %s\\n", incident.ID)\n\tfmt.Printf("MTTR (Mean Time To Recovery): %v\\n", incident.MTTR())\n\tfmt.Printf("Root Cause: %s\\n", incident.RootCause)\n\tfmt.Println("Action Items: Add linter check for missing DB indexes in CI/CD pipeline")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"PAGERDUTY ALERT TRIGGERED","incident_id":"INC-88912","alert":"HighLatency p95 > 500ms","slack_channel":"#incidents-2026-09-02"}\n# \n# --- Runbook Checklist ---\n#  [x] 1. Check Grafana dashboard (Latency spike detected)\n#  [x] 2. Check recent deployments (v2.14.1 deployed 15m ago)\n#  [x] 3. Check error logs (DB index missing)\n#  [x] 4. Mitigation: Rollback to v2.14.0 executed\n# \n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"INCIDENT RESOLVED","incident_id":"INC-88912","mttr":720000000000,"root_cause":"Bad deployment v2.14.1 (unindexed query)"}\n# \n# === Post-Mortem Summary ===\n# Incident ID: INC-88912\n# MTTR (Mean Time To Recovery): 12m0s\n# Root Cause: Bad deployment v2.14.1 (unindexed query)\n# Action Items: Add linter check for missing DB indexes in CI/CD pipeline'}], 'under_the_hood': 'Метрика MTTR (Mean Time To Recovery) измеряет время от момента возникновения инцидента до полного восстановления сервиса.', 'pitfalls': 'Культура Blameless Post-Mortem (безупречный разбор полетов) фокусируется на улучшении процессов и автоматики, а не на поиске виноватых людей.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем разница между MTTR и MTBF в SRE?»\n**Ответ:** MTTR (Mean Time To Recovery) — среднее время ликвидации аварии. MTBF (Mean Time Between Failures) — среднее время безаварийной работы системы между сбоями.'}, {'num': 56, 'title': 'Создание кастомного логгера log.New с направлением в os.Stderr', 'task': 'Создай кастомный логгер с помощью `log.New()`. Направь его вывод в `os.Stderr`.', 'theory': 'Направление ошибок в `os.Stderr` позволяет операционной системе и контейнерным агентам отделять поток ошибок от стандартного вывода программы.', 'step_by_step': '1. Создадим `errLogger := log.New(os.Stderr, "[ERROR] ", log.Ldate|log.Ltime|log.Lshortfile)`.\n2. Запишем ошибку через `errLogger.Println`.\n3. В `main` убедимся в корректной работе.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\t// Кастомный логгер критических ошибок с выводом в поток Stderr\n\terrLogger := log.New(os.Stderr, "[ERROR] ", log.Ldate|log.Ltime|log.Lshortfile)\n\n\terrLogger.Println("Не удалось подключиться к серверу очередей RabbitMQ")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод (в поток Stderr):\n# [ERROR] 2026/09/02 18:40:00 main.go:11: Не удалось подключиться к серверу очередей RabbitMQ'}], 'under_the_hood': '`os.Stderr` в Linux соответствует файловому дескриптору `2` (STDERR_FILENO).', 'pitfalls': 'Запись в `os.Stderr` не буферизируется в терминале, что обеспечивает немедленное отображение критических ошибок.', 'bigtech_interview': '**Вопрос с собеседования:** «Как перенаправить поток Stderr процесса Go в файл через оболочку Linux?»\n**Ответ:** С помощью оператора перенаправления `2>`: `./app 2> error.log` (или `> all.log 2>&1` для объединения stdout и stderr).'}]
